function alertsTick(){if(!config||!config.alerts)return;const now=new Date(),date=now.toISOString().slice(0,10),hm=now.toTimeString().slice(0,5);const schedule=(enabled:boolean,time:string,key:string,text:string,voice:string)=>{const id=date+':'+key;if(enabled&&hm===time&&!alertKeys.has(id)){alertKeys.add(id);systemNotice(text,voice);}};schedule(config.alerts.morningEnabled,config.alerts.morningTime,'morning','早上好，博士。今天也请按自己的节奏开始吧。','cn_042');schedule(config.alerts.lunchEnabled,config.alerts.lunchTime,'lunch','博士，中午了，记得吃饭和喝水。','cn_033');schedule(config.alerts.nightEnabled,config.alerts.nightTime,'night','已经很晚了，博士。今天先休息一下吧。','cn_010');if(config.alerts.waterEnabled&&Date.now()>=waterNextAt){waterNextAt=Date.now()+config.alerts.waterIntervalMinutes*60*1000;systemNotice('博士，喝口水吧。','cn_033');}if(pomodoro.running&&Date.now()>=pomodoro.nextAt){if(pomodoro.phase==='focus'){pomodoro.cyclesCompleted+=1;if(pomodoro.cyclesCompleted>=pomodoro.cyclesTotal){pomodoro={...pomodoro,running:false,phase:'done',remainingSeconds:0,nextAt:0};systemNotice('专注计划完成了，博士。辛苦了，请休息一下。','cn_031');}else{pomodoro={...pomodoro,phase:'break',remainingSeconds:Math.round(config.alerts.breakMinutes*60),nextAt:Date.now()+Math.round(config.alerts.breakMinutes*60)*1000};systemNotice('专注时间结束了，博士。请休息一下。','cn_031');}}else{pomodoro={...pomodoro,phase:'focus',remainingSeconds:Math.round(config.alerts.focusMinutes*60),nextAt:Date.now()+Math.round(config.alerts.focusMinutes*60)*1000};systemNotice('休息结束，我们继续前进吧，博士。','cn_042');}broadcastAlertStatus();}else if(pomodoro.running){pomodoro.remainingSeconds=Math.max(0,Math.ceil((pomodoro.nextAt-Date.now())/1000));}if(config.alerts.stoneBugEnabled&&Date.now()>=stoneBugNextAt){stoneBugNextAt=Date.now()+config.alerts.stoneBugIntervalMinutes*60*1000;spawnStoneBug();}if(alertKeys.size>500)for(const k of [...alertKeys].slice(0,100))alertKeys.delete(k);}

