 if(shouldRunAutonomousCycle(autonomousState)&&now>=p.nextAction&&(!p.holdUntil||now>=p.holdUntil)){if(Math.random()<.5){const pool=autonomousActions<any>(currentActions(p),c.behaviour.actionGroup,c.behaviour.customActionIds);const move=pool.find((v:any)=>isMovementActionName(v.name))||pool.find((v:any)=>isStandbyActionName(v.name));if(move)sendAction(p,isMovementActionName(move.name)?move:{...move,__traverse:true},false,true);else randomAction(p);}else randomAction(p);}
